// WF-99 Error Handler — Extract error details
const errorData = $input.all();
const item = errorData[0].json;

// Extract error information from the error trigger
const execution = item.execution || {};
const workflow = item.workflow || {};

const errorEvent = {
  event_id: $now.toISO().replace(/[^0-9]/g, '').slice(0, 17) + '-' + Math.random().toString(36).slice(2, 8),
  timestamp: $now.toISO(),
  workflow: workflow.name || 'UNKNOWN',
  entity_type: 'WORKFLOW_ERROR',
  entity_id: execution.id || 'UNKNOWN',
  event_type: 'ERROR',
  details_json: JSON.stringify({
    workflow_id: workflow.id || null,
    workflow_name: workflow.name || null,
    execution_id: execution.id || null,
    error_message: execution.error?.message || item.error?.message || 'Unknown error',
    error_node: execution.lastNodeExecuted || null,
    error_stack: (execution.error?.stack || item.error?.stack || '').slice(0, 500),
    mode: execution.mode || null,
    retryOf: execution.retryOf || null
  })
};

// Determine if this is a critical error that needs alerting
const criticalPatterns = [
  'gmail', 'quota', 'attachment', 'groq', 'sheets', 'bounce',
  'rate limit', 'authentication', 'unauthorized', '429', '403'
];
const errorMsg = (execution.error?.message || item.error?.message || '').toLowerCase();
const isCritical = criticalPatterns.some(p => errorMsg.includes(p));

return [{
  json: {
    ...errorEvent,
    is_critical: isCritical,
    alert_message: isCritical 
      ? `⚠️ CRITICAL ERROR in ${workflow.name || 'unknown workflow'}: ${execution.error?.message || 'Unknown'}` 
      : null
  }
}];

// For critical errors, prepare alert notification
// In production this could send an email or Telegram message
// For now, we log it prominently
const item = $input.first().json;

console.log('=== CRITICAL ERROR ALERT ===');
console.log(item.alert_message);
console.log('Details:', item.details_json);
console.log('===========================');

return [{
  json: {
    alert_sent: true,
    alert_message: item.alert_message,
    timestamp: item.timestamp,
    workflow: item.workflow
  }
}];
